#!/usr/bin/env python3
"""Write docs/STATUS.md deterministically (no timestamps). Use --print to only print."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from plan_lib import ROOT, STATUSES, GATES, parse_plan, current_gate, log_files, log_summary, adr_files, adr_status


def render():
    rows, _ = parse_plan()
    out = ["# Status", "",
           "Generated by `python3 scripts/build_status.py`. Do not edit by hand.", "",
           f"Current gate: {current_gate()} (see [GATES.md](GATES.md))", "",
           "## Plan progress by gate", "",
           "| Gate | todo | doing | done | blocked | total |", "|---|---|---|---|---|---|"]
    for g in GATES:
        gr = [r for r in rows if r["Gate"] == g]
        counts = [sum(1 for r in gr if r["Status"] == s) for s in STATUSES]
        out.append(f"| {g} | " + " | ".join(map(str, counts)) + f" | {len(gr)} |")
    counts = [sum(1 for r in rows if r["Status"] == s) for s in STATUSES]
    out.append("| all | " + " | ".join(map(str, counts)) + f" | {len(rows)} |")
    out += ["", "## Blocked items", ""]
    blocked = [r for r in rows if r["Status"] == "blocked"]
    out += [f"- {r['ID']}: {r['Item']} ({r['Gate']})" for r in blocked] or ["- none"]
    out += ["", "## Doing items without an owner", ""]
    noown = [r for r in rows if r["Status"] == "doing" and r["Owner"] == "unassigned"]
    out += [f"- {r['ID']}: {r['Item']}" for r in noown] or ["- none"]
    out += ["", "## Items in progress", ""]
    doing = [r for r in rows if r["Status"] == "doing"]
    out += [f"- {r['ID']}: {r['Item']} ({r['Owner']})" for r in doing] or ["- none"]
    out += ["", "## Last 10 log files", ""]
    logs = log_files()[:10]
    out += [f"- [{f.name}](log/{f.name}): {log_summary(f)}" for f in logs] or ["- none yet"]
    out += ["", "## ADRs with status Proposed", ""]
    prop = [f for f in adr_files() if adr_status(f).lower().startswith("proposed")]
    out += [f"- [{f.stem}](decisions/{f.name})" for f in prop] or ["- none"]
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    text = render()
    if "--print" in sys.argv:
        print(text, end="")
    else:
        (ROOT / "docs" / "STATUS.md").write_text(text, encoding="utf-8")
        print("wrote docs/STATUS.md")
